    int n = noc / out_channels;
    int group = oc / out_channels_per_group;
    int oc_in_group = oc % out_channels_per_group;
    int ic_start = group * in_channels_per_group;
    for (int i = threadIdx.x; i < weight_size; i += blockDim.x) {
