        int rem = i % kElems;
        int ic = ic_start + ic_local;
        long weight_idx = ((long)ic * out_channels_per_group + oc_in_group) * kElems + rem;
        s_weight[i] = weight[weight_idx];
    }
    int tile_idx = blockIdx.x;
    int tile_w_idx = tile_idx % tiles_w;
    int tmp_tile = tile_idx / tiles_w;
    int tile_h_idx = tmp_tile % tiles_h;
    int tile_d_idx = tmp_tile / tiles_h;
    int od0 = tile_d_idx * TILE_D;
    int oh0 = tile_h_idx * TILE_H;
    int ow0 = tile_w_idx * TILE_W;
    int t_d_min = od0 + pad_d - (kD - 1) * dil_d;
    int id_min = (t_d_min >= 0) ? (t_d_min / stride_d) : -(((-t_d_min) + stride_d - 1) / stride_d);
    int t_h_min = oh0 + pad_h - (kH - 1) * dil_h;
    int ih_min = (t_h_min >= 0) ? (t_h_min / stride_h) : -(((-t_h_min) + stride_h - 1) / stride_h);
    int t_w_min = ow0 + pad_w - (kW - 1) * dil_w;
    int iw_min = (t_w_min >= 0) ? (t_w_min / stride_w) : -(((-t_w_min) + stride_w - 1) / stride_w);
    int tid = threadIdx.x;
    int local_tw = tid % HALF_TILE_W;
    int tmp_l = tid / HALF_TILE_W;
    int local_th = tmp_l % TILE_H;
    int local_td = tmp_l / TILE_H;
    int od = od0 + local_td;
    int oh = oh0 + local_th;
    int ow_a = ow0 + local_tw;
    int ow_b = ow0 + local_tw + HALF_TILE_W;
    bool valid_out_a = (od < D_out) && (oh < H_out) && (ow_a < W_out);
    bool valid_out_b = (od < D_out) && (oh < H_out) && (ow_b < W_out);
    float sum_a = 0.0f;
    float sum_b = 0.0f;
    int tile_vol = size_d * size_h * size_w;
    for (int ic_local = 0; ic_local < in_channels_per_group; ic_local++) {
        __syncthreads();
        int ic = ic_start + ic_local;
        for (int idx = threadIdx.x; idx < tile_vol; idx += blockDim.x) {
            int lw = idx % size_w;
            int tmp2 = idx / size_w;
            int lh = tmp2 % size_h;
            int ld = tmp2 / size_h;
