                val = input[input_idx];
            }
            s_input[idx] = val;
        }
        __syncthreads();
        if (valid_out_a || valid_out_b) {
            for (int kd = 0; kd < kD; kd++) {
                int t_d = od + pad_d - kd * dil_d;
                if (t_d % stride_d != 0) continue;
                int id = t_d / stride_d;
                if (id < 0 || id >= D_in) continue;
                int ld = id - id_min;
