                                int iw_b = t_w_b / stride_w;
                                if (iw_b >= 0 && iw_b < W_in) {
                                    int lw_b = iw_b - iw_min;
                                    int s_idx_input_b = (ld * size_h + lh) * size_w + lw_b;
                                    sum_b += s_input[s_idx_input_b] * wv;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
