        output[output_idx_a] = out_a;
    }
    if (valid_out_b) {
        float out_b = sum_b;
        if (has_bias) {
            out_b += bias[oc];
        }
        long output_idx_b = (((long)n * out_channels + oc) * D_out + od) * H_out * W_out + (long)oh * W_out + ow_b;
