    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t out_pad_d, int64_t out_pad_h, int64_t out_pad_w,
    int64_t dil_d, int64_t dil_h, int64_t dil_w,
    int64_t groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int in_channels = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int out_channels_per_group = weight.size(1);
    int out_channels = out_channels_per_group * groups;
    int kD = weight.size(2);
    int kH = weight.size(3);
    int kW = weight.size(4);
    int in_channels_per_group = in_channels / groups;
    int D_out = (D_in - 1) * stride_d - 2 * pad_d + dil_d * (kD - 1) + out_pad_d + 1;
    int H_out = (H_in - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + out_pad_h + 1;
    int W_out = (W_in - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + out_pad_w + 1;
    auto output = torch::zeros({N, out_channels, D_out, H_out, W_out}, input.options());
    bool has_bias = bias.defined() && bias.numel() > 0;
    int stride_d_i = (int)stride_d, stride_h_i = (int)stride_h, stride_w_i = (int)stride_w;
    int pad_d_i = (int)pad_d, pad_h_i = (int)pad_h, pad_w_i = (int)pad_w;
    int dil_d_i = (int)dil_d, dil_h_i = (int)dil_h, dil_w_i = (int)dil_w;
    int tiles_d = (D_out + TILE_D - 1) / TILE_D;
    int tiles_h = (H_out + TILE_H - 1) / TILE_H;
    int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    int diff_d = (TILE_D - 1) + (kD - 1) * dil_d_i;
    int size_d = (diff_d + stride_d_i - 1) / stride_d_i + 1;
    int diff_h = (TILE_H - 1) + (kH - 1) * dil_h_i;
    int size_h = (diff_h + stride_h_i - 1) / stride_h_i + 1;
    int diff_w = (TILE_W - 1) + (kW - 1) * dil_w_i;
    int size_w = (diff_w + stride_w_i - 1) / stride_w_i + 1;
    int weight_size = in_channels_per_group * kD * kH * kW;
