        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, in_channels, out_channels,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        kD, kH, kW,
        stride_d_i, stride_h_i, stride_w_i,
        pad_d_i, pad_h_i, pad_w_i,
        dil_d_i, dil_h_i, dil_w_i,
